volatile int count = 0;
volatile int last_clk = HIGH;
void IRAM_ATTR isr() {
    int c = digitalRead({{clk_pin}});
    if (c != last_clk && c == LOW) {
        count += (digitalRead({{dt_pin}}) != c) ? 1 : -1;
    }
    last_clk = c;
}
void setup() {
    pinMode({{clk_pin}}, INPUT_PULLUP);
    pinMode({{dt_pin}}, INPUT_PULLUP);
    attachInterrupt(digitalPinToInterrupt({{clk_pin}}), isr, CHANGE);
}
